import "strings"

// Decodes reversed dummy token
var obfuscatedToken = "yd4m3x3lpmax3_kca_t3rc3s"

func GetKey() string {
	r := []rune(obfuscatedToken)
	for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 {
		r[i], r[j] = r[j], r[i]
	}
	return strings.ReplaceAll(string(r), "3", "e")
}"}

